p.me:
\begin{array}{c|c|c}
\textbf{population size} \amp 1-\dfrac{P}{K} \amp \textbf{model behavior}\\
\hline
P\ll K \amp \approx1 \amp P'\approx rP,\ \text{almost exponential}\\
P=K/2 \amp 1/2 \amp \text{growth still positive}\\
P=K \amp 0 \amp \text{growth stops}\\
P>K \amp <0 \amp \text{population decreases}
\end{array}

