p.me:
\begin{array}{c|c}
\textbf{early stage} \amp P\ll K,\quad P'\approx rP,\quad \text{almost exponential}\\
\textbf{middle stage} \amp P\approx K/2,\quad \text{growth is fastest}\\
\textbf{late stage} \amp P\approx K,\quad P'\approx0,\quad \text{growth slows}
\end{array}

\begin{array}{ll}
\text{1.} \amp \text{the carrying capacity \(K\) is fixed,}\\
\text{2.} \amp \text{the early growth rate \(r\) is fixed,}\\
\text{3.} \amp \text{the slowing factor is linear in \(P\),}\\
\text{4.} \amp \text{there are no delays, shocks, seasons, migrations, or changing behavior.}
\end{array}
